function minimumJumps(forbidden, a, b, x) {
  const blocked = new Set(forbidden);
  const limit = Math.max(x, ...forbidden) + a + b;
  const seen = [new Array(limit + 1).fill(false), new Array(limit + 1).fill(false)];
  seen[0][0] = true;
  let queue = [[0, 0]];
  let jumps = 0;

  while (queue.length > 0) {
    const next = [];
    for (const [position, wentBack] of queue) {
      if (position === x) {
        return jumps;
      }
      const forward = position + a;
      if (forward <= limit && !blocked.has(forward) && !seen[0][forward]) {
        seen[0][forward] = true;
        next.push([forward, 0]);
      }
      const backward = position - b;
      if (wentBack === 0 && backward >= 0 && !blocked.has(backward) && !seen[1][backward]) {
        seen[1][backward] = true;
        next.push([backward, 1]);
      }
    }
    queue = next;
    jumps++;
  }
  return -1;
}

