function minimumJumps(forbidden, a, b, x) {
  // Different model: a left jump is always followed by a right jump, so treat the pair as one
  // move of cost 2 and search positions only, cheapest cost first (bucket queue), with a wide right edge.
  const top = 3 * (Math.max(x, ...forbidden) + a + b);
  const bad = new Set(forbidden);
  const cost = new Array(top + 1).fill(Infinity);
  const buckets = [[0]];
  cost[0] = 0;
  let answer = Infinity;
  const offer = (p, c) => {
    if (p > top || bad.has(p) || c >= cost[p]) return;
    cost[p] = c;
    while (buckets.length <= c) buckets.push([]);
    buckets[c].push(p);
  };
  for (let c = 0; c < buckets.length; c++) {
    for (const p of buckets[c]) {
      if (cost[p] !== c) continue;
      if (p === x) answer = Math.min(answer, c);
      offer(p + a, c + 1);
      const low = p - b;
      if (low < 0 || bad.has(low)) continue;
      if (low === x) answer = Math.min(answer, c + 1);
      offer(low + a, c + 2);
    }
  }
  return answer === Infinity ? -1 : answer;
}

