function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const span = size === 'large' ? 2000 : 24;
  const step = size === 'large' ? 2000 : 9;
  const roll = rand();
  let a = int(1, step);
  let b = int(1, step);
  if (size === 'large' && roll < 0.5) {
    // Small steps make long, interesting paths.
    a = int(1, 60);
    b = int(1, 60);
  }
  const x = rand() < 0.05 ? 0 : int(0, span);
  const count = size === 'large' ? int(1, roll < 0.5 ? 200 : 1000) : int(1, 7);
  const values = new Set();
  while (values.size < count) {
    const v = int(1, span);
    if (v !== x) values.add(v);
  }
  const forbidden = [...values];
  return [forbidden, a, b, x];
}
